Tool response:
Tool: find_employee_by_user_and_company
Description: Locate an employee record using their user ID and company ID.
Parameters:
    {
      "type": "object",
      "properties": {
        "user_id": {
          "type": "integer",
          "description": "Internal ID of the user",
          "title": "User Id"
        },
        "company_id": {
          "type": "integer",
          "description": "Internal ID of the company",
          "title": "Company Id"
        }
      },
      "required": [
        "user_id",
        "company_id"
      ]
    }

Tool response:
Tool: find_employee_equity_grants
Description: Retrieve all equity grants for a given employee, filtered by grant type and status if specified.
Parameters:
    {
      "type": "object",
      "properties": {
        "employee_id": {
          "type": "integer",
          "description": "Internal ID of the employee",
          "title": "Employee Id"
        },
        "grant_type": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Type of equity grant (e.g., ISO, NSO)",
          "title": "Grant Type"
        },
        "status": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Current status of the grant (e.g., pending, accepted)",
          "title": "Status"
        }
      },
      "required": [
        "employee_id"
      ]
    }

Tool response:
Tool: update_equity_grant_status
Description: Change the status of a specific equity grant to 'accepted'.
Parameters:
    {
      "type": "object",
      "properties": {
        "grant_id": {
          "type": "integer",
          "description": "Internal ID of the equity grant",
          "title": "Grant Id"
        },
        "status": {
          "type": "string",
          "pattern": "^accepted$",
          "title": "Status",
          "description": "New status for the equity grant"
        }
      },
      "required": [
        "grant_id",
        "status"
      ]
    }

Tool response:
Tool: record_grant_document_collection
Description: Log that a specific document related to an equity grant has been collected.
Parameters:
    {
      "type": "object",
      "properties": {
        "grant_id": {
          "type": "integer",
          "title": "Grant Id"
        },
        "document_type": {
          "type": "string",
          "pattern": "^(equity_agreement|tax_form)$",
          "title": "Document Type"
        },
        "file_path": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "File Path"
        },
        "collected_by": {
          "type": "integer",
          "title": "Collected By"
        }
      },
      "required": [
        "grant_id",
        "document_type",
        "collected_by"
      ]
    }
